; ============================================================================
; bg_tiles — 8x8 background tileset (Tome of the Dead side-view scene)
; Generated by tools/gfx_convert.py on 2026-06-29
; Source        : bg_tiles.grid
; Layout        : 5 tiles x 8 bitmap bytes (MSB=left), row-major
;                 parallel attr table, one attribute byte per tile
; Clash         : each tile is one paper+ink — clash-legal by construction
; Intended use  : draw_cell background (floor/pillar/doorway/blank)
; ============================================================================
bg_tiles:
bg_tiles_blank:
        DEFB $00,$00,$00,$00,$00,$00,$00,$00    ; blank
bg_tiles_floor:
        DEFB $FF,$49,$00,$92,$00,$49,$00,$92    ; floor
bg_tiles_ground:
        DEFB $00,$24,$00,$92,$00,$49,$00,$92    ; ground
bg_tiles_pillar:
        DEFB $7E,$42,$42,$42,$42,$42,$42,$7E    ; pillar
bg_tiles_doorway:
        DEFB $FF,$81,$81,$81,$81,$81,$81,$81    ; doorway

bg_tiles_attr:
        DEFB $05    ; blank    ink=cyan paper=black bright=0
        DEFB $4F    ; floor    ink=white paper=blue bright=1
        DEFB $4F    ; ground   ink=white paper=blue bright=1
        DEFB $05    ; pillar   ink=cyan paper=black bright=0
        DEFB $05    ; doorway  ink=cyan paper=black bright=0
bg_tiles_count EQU 5
